def count_words(text):
    words = text.lower().split()
    word_counts = {}
    for word in words:
        # Entfernt Satzzeichen am Anfang und Ende des Wortes
        word = word.strip('.,!?;:()[]"\'')
        if word:
            word_counts[word] = word_counts.get(word, 0) + 1
    return word_counts
```

